"""Migrated Meridian CRM account validation rules."""

from typing import Any


def _value(row: dict | None, field: str) -> Any:
    if row is None:
        return ""
    value = row.get(field, "")
    return "" if value is None else value


def _number(value: Any) -> float:
    """Apply legacy numeric-context coercion for the values used by these rules."""
    if value is None or value == "":
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(str(value).strip())
    except (TypeError, ValueError):
        return 0.0


def _length(value: Any) -> int:
    return len("" if value is None else str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image against migrated VRL rules."""
    del today  # Present for the fixed interface; unused by these rules.

    errors: list[dict] = []
    record = record or {}
    old_record = old if event == "UPDATE" and old is not None else {}

    # ACC-001
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "ACCT_NM")) < 2:
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

    # ACC-002
    if event in ("INSERT", "UPDATE"):
        if _value(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

    # ACC-003
    if event in ("INSERT", "UPDATE"):
        if _number(_value(record, "ANN_REV")) < 0:
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

    # ACC-004
    if event == "UPDATE":
        releasing_zero_limit = (
            _value(old_record, "CRED_HOLD") == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= 0
        )
        if releasing_zero_limit:
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    # ACC-005
    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "REGION_CD")) != 3:
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
